const buildPrompt = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Build Website Brief Prompt',
    parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Turns the Lead Intake hand-off into the Website Builder's user prompt. Facts only; nothing is invented here.\nconst USER_PROMPT_TEMPLATE = \"Prepare the website build brief for this prospect.\\n\\nTenant: {{tenant_id}}\\nLead id: {{lead_id}}\\nNow (UTC): {{now}}\\n\\nContact details as given:\\n- Name: {{contact_name}}\\n- Company: {{company_name}}\\n- Industry: {{industry}}\\n- Email: {{email}}\\n- Phone: {{phone}}\\n\\nSales consultant's summary of the lead:\\n{{sales_summary}}\\n\\nFacts the sales consultant extracted (JSON, null = unknown):\\n{{extracted_json}}\\n\\nConversation with the customer (oldest first; the last customer message is the current one):\\n{{conversation}}\\n\\nCurrent customer message:\\n\\\"\\\"\\\"\\n{{message}}\\n\\\"\\\"\\\"\\n\\nWEBSITE_CREATOR_BRIEF from the Website Intelligence agent (research already done; authoritative for facts, objective, CTAs, sitemap and placeholders; empty when John's hand-off came straight to you):\\n\\\"\\\"\\\"\\n{{research_brief}}\\n\\\"\\\"\\\"\\n\\nReturn the JSON object now.\\n\";\nconst inp = $input.first().json || {};\nconst str = (v) => (v === undefined || v === null || v === '' ? null : String(v));\nlet conversation = [];\ntry { conversation = JSON.parse(inp.conversation_json || '[]'); } catch (e) { conversation = []; }\nif (!Array.isArray(conversation)) conversation = [];\nlet extracted = {};\ntry { extracted = JSON.parse(inp.extracted_json || '{}'); } catch (e) { extracted = {}; }\nif (!extracted || typeof extracted !== 'object') extracted = {};\nconst testMode = inp.test_mode === true || inp.test_mode === 'true';\nconst now = new Date().toISOString();\nconst input = {\n  tenant_id: str(inp.tenant_id) || 'fusiontech',\n  lead_id: str(inp.lead_id) || ('lead_unknown_' + Date.now().toString(36)),\n  contact_name: str(inp.contact_name), company_name: str(inp.company_name), industry: str(inp.industry) || str(extracted.industry),\n  email: str(inp.email), phone: str(inp.phone), channel: str(inp.channel) || 'unknown',\n  message: str(inp.message) || '', conversation, sales_summary: str(inp.sales_summary) || '', extracted,\n  test_mode: testMode, notify_email: str(inp.notify_email) || \"ryandhana1515@gmail.com\", source_execution_id: str(inp.source_execution_id),\n  research_brief: str(inp.research_brief) || '', research_json: str(inp.research_json) || ''\n};\nconst convoText = conversation.map((m) => '- [' + (m.role || 'customer') + (m.ts ? ' ' + m.ts : '') + '] ' + m.content).join('\\n') || '(none)';\nconst vars = {\n  tenant_id: input.tenant_id, lead_id: input.lead_id, now, contact_name: input.contact_name || 'not given', company_name: input.company_name || 'not given',\n  industry: input.industry || 'not given', email: input.email || 'not given', phone: input.phone || 'not given',\n  sales_summary: input.sales_summary || '(none)', extracted_json: JSON.stringify(extracted), conversation: convoText, message: input.message || '(no message)',\n  research_brief: input.research_brief || '(none — no research brief; use John\\'s hand-off only)'\n};\nconst user_prompt = USER_PROMPT_TEMPLATE.replace(/\\{\\{(\\w+)\\}\\}/g, (_, k) => (k in vars ? String(vars[k]) : ''));\nreturn [{ json: { input, user_prompt, started_at: now, config: { model: \"claude-sonnet-4-6\", agent: \"website-builder\", agent_version: \"2.2.0\" }, execution_id: String($execution.id), workflow_id: String($workflow.id) } }];\n" },
    position: [220, 300]
  },
  output: [{ input: { tenant_id: 'fusiontech', lead_id: 'lead_x', message: 'I want a website', conversation: [], extracted: {}, test_mode: true, notify_email: 'owner@example.com' }, user_prompt: 'Prepare the website build brief...', started_at: '2026-01-01T00:00:00.000Z', config: { model: "claude-sonnet-4-6", agent: 'website-builder', agent_version: '2.0.0' }, execution_id: '1', workflow_id: 'w' }]
});

