const note = sticky("## CEO Brain — Website Builder v2.1 (Agent #2)\nCalled by Lead Intake once John has the customer's details. Two modes: SME and Medical.\n\nFlow: build prompt → design standard + playbook live from the vault → Claude (Gateway) → validate + mode guard + fallback → cinematic brief + Lovable prompt + image shot list → Decide Build (auto-build policy: one build per lead, daily cap) → task, run, audit → Start Website Build Runner (Higgsfield/Kling photography → Lovable → Website Build Record → John sends the link) → owner copy.\n\nSource of truth: repo ryan/ceo-brain (workflows/website-builder/build.js). Do not hand-edit Code nodes.", [whenCalled, buildPrompt, loadStandard, loadPlaybook, composeSystem], { color: 4 });

export default workflow('ceo-brain-website-builder', 'CEO Brain — Website Builder')
  .add(whenCalled)
  .to(buildPrompt)
  .to(loadStandard)
  .to(loadPlaybook)
  .to(composeSystem)
  .to(claudeAgent.to(finalize))
  .add(claudeAgent.onError(finalize))
  .add(finalize)
  .to(loadTasks)
  .to(decideBuild)
  .to(upsertTask)
  .to(logRun)
  .to(logAudit)
  .to(buildGate
    .onTrue(startRunner.to(emailOwner))
    .onFalse(emailOwner))
  .add(note)
  .group('1. Brief generation', [buildPrompt, loadStandard, loadPlaybook, composeSystem, claudeAgent, finalize], { description: 'Prompt, standard + playbook from the vault, Claude, validate, fallback, Lovable prompt, image shots.' })
  .group('2. Decide & build', [loadTasks, decideBuild, upsertTask, logRun, logAudit, buildGate, startRunner, emailOwner], { description: 'Auto-build policy: one build per lead + daily cap; task, run, audit; start the Website Build Runner; owner copy by email.' });
